const TIME_LIMIT: int = 1200;
const OPENING_BUFFER: int = 120;
const TH18_RICE: int = 480;

async sub shooter() {
    wait(60);
    var rank: int = global(GVAR_RANK);
    var n: int = 12;
    var rounds: int = 2;
    var speed: fx = 1.6fx;
    if rank == 1 { n = 12; rounds = 5; speed = 1.6fx; }
    if rank == 2 { n = 15; rounds = 15; speed = 2.6fx; }
    if rank == 3 { n = 12; rounds = 35; speed = 2.6fx; }
    var alpha: angle = 0deg;
    sh_reset(0);
    sh_sprite(0, TH18_RICE, 8);
    sh_ring(0, 1);
    sh_aim(0, 1);
    sh_count(0, n, 1);
    sh_speed(0, speed, 0fx);
    sh_dist(0, -4fx*speed);
    sh_angle(0, alpha, 3deg);
    for i in 0..rounds {
        sh_angle(0, alpha, 3deg);
        sh_fire(0);
        alpha = alpha + 222.5deg;
        var interval: int = 140;
        if rank == 1 { interval = 60; }
        if rank == 2 { interval = 20; }
        if rank == 3 { interval = 10; }
        wait(interval);
    }
}

async sub girl() {
    set_invuln(65535);
    set_hurtbox(16fx);
    set_hitbox(12fx);
    // Source st01::GirlD01: moveVel(π/2,4), then mode-1 turn to π/2 at 60f;
    // source direction stays downward. Target begins at the source position.
    move_vel(0, 90deg, 4fx, EASE_LINEAR);
    move_vel(60, 90deg, 0fx, EASE_QUAD_IN);
    spawn shooter();
    wait(320);
    move_speed(120, 2.5fx, EASE_QUAD_IN);
    wait(60);
    loop { wait(600); }
}

async sub wave() {
    wait(OPENING_BUFFER);
    // Source MainSub03 creates (-120,-88), (0,-24), (+120,-88) at one tick.
    _ = spawn_enemy(-120fx, -88fx, 1000, 0, 0, 0, girl);
    _ = spawn_enemy(0fx, -24fx, 1000, 0, 0, 0, girl);
    _ = spawn_enemy(120fx, -88fx, 1000, 0, 0, 0, girl);
    wait(TIME_LIMIT - OPENING_BUFFER);
    loop { wait(600); }
}

async sub encounter() {
    // Training-only phase owner has no source body collision.
    set_enemy_flag(ENEMY_NO_BODY, 1);
    set_invuln(65535);
    phase_begin(0, wave, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(600); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, encounter);
    loop { wait(600); }
}
